        "evidence_ids": ["E_d6fd3723dbb7"],
        "support": [
          {
            "evidence_id": "E_d6fd3723dbb7",
            "quote": "The sequence of events that result in the contraction of an individual muscle fiber begins with a signal—the neurotransmitter, ACh—from the motor neuron innervating that fiber.",
