        "effect_state_refs": ["ST_SARCOLEMMA_REPOLARIZED", "ST_CA_RETURNED_TO_SR", "ST_ACTIN_SITES_SHIELDED", "ST_FIBRE_RELAXED"],
        "terminates_state_refs": ["ST_SARCOMERE_SHORTENED", "ST_ACTIN_SITES_UNSHIELDED", "ST_CA_IN_SARCOPLASM"]
